#include <vector>
#include <algorithm>

class Solution {
public:
    int minSwaps(std::vector<std::vector<int>>& grid) {
        int n = grid.size();
        std::vector<int> zeros(n);
        for (int i = 0; i < n; ++i) {
            int cnt = 0;
            for (int j = n - 1; j >= 0 && grid[i][j] == 0; --j) cnt++;
            zeros[i] = cnt;
        }
        int ans = 0;
        for (int i = 0; i < n; ++i) {
            int needed = n - 1 - i;
            int matched = -1;
            for (int j = i; j < n; ++j) {
                if (zeros[j] >= needed) {
                    matched = j;
                    break;
                }
            }
            if (matched == -1) return -1;
            ans += matched - i;
            int val = zeros[matched];
            zeros.erase(zeros.begin() + matched);
            zeros.insert(zeros.begin() + i, val);
        }
        return ans;
    }
};

import java.util.*;

class Solution {
    public int minSwaps(int[][] grid) {
        int n = grid.length;
        List<Integer> zeros = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            int cnt = 0;
            for (int j = n - 1; j >= 0 && grid[i][j] == 0; j--) cnt++;
            zeros.add(cnt);
        }
        int ans = 0;
        for (int i = 0; i < n; i++) {
            int needed = n - 1 - i;
            int matched = -1;
            for (int j = i; j < n; j++) {
                if (zeros.get(j) >= needed) {
                    matched = j;
                    break;
                }
            }
            if (matched == -1) return -1;
            ans += matched - i;
            int val = zeros.remove(matched);
            zeros.add(i, val);
        }
        return ans;
    }
}

var minSwaps = function(grid) {
    const n = grid.length;
    const zeros = [];
    for (let i = 0; i < n; i++) {
        let cnt = 0;
        for (let j = n - 1; j >= 0 && grid[i][j] === 0; j--) cnt++;
        zeros.push(cnt);
    }
    let ans = 0;
    for (let i = 0; i < n; i++) {
        const needed = n - 1 - i;
        let matched = -1;
        for (let j = i; j < n; j++) {
            if (zeros[j] >= needed) {
                matched = j;
                break;
            }
        }
        if (matched === -1) return -1;
        ans += matched - i;
        const val = zeros.splice(matched, 1)[0];
        zeros.splice(i, 0, val);
    }
    return ans;
};
